is_balanced:
def is_balanced(s):
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opens = set(pairs.values())
    for ch in s:
        if ch in opens:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

two_sum:
def two_sum(nums, target):
    seen = {}
    for i, n in enumerate(nums):
        if target - n in seen:
            return [seen[target - n], i]
        seen[n] = i
    return []

roman_to_int:
def roman_to_int(s):
    vals = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
    total = 0
    prev = 0
    for ch in reversed(s):
        v = vals[ch]
        if v < prev:
            total -= v
        else:
            total += v
            prev = v
    return total

merge_intervals:
def merge_intervals(intervals):
    if not intervals:
        return []
    intervals = sorted(intervals, key=lambda x: x[0])
    out = [list(intervals[0])]
    for s, e in intervals[1:]:
        if s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return out

longest_unique:
def longest_unique(s):
    last = {}
    start = 0
    best = 0
    for i, ch in enumerate(s):
        if ch in last and last[ch] >= start:
            start = last[ch] + 1
        last[ch] = i
        best = max(best, i - start + 1)
    return best

spiral_order:
def spiral_order(matrix):
    if not matrix or not matrix[0]:
        return []
    res = []
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1
    while top <= bottom and left <= right:
        for c in range(left, right + 1):
            res.append(matrix[top][c])
        top += 1
        for r in range(top, bottom + 1):
            res.append(matrix[r][right])
        right -= 1
        if top <= bottom:
            for c in range(right, left - 1, -1):
                res.append(matrix[bottom][c])
            bottom -= 1
        if left <= right:
            for r in range(bottom, top - 1, -1):
                res.append(matrix[r][left])
            left += 1
    return res

word_break:
def word_break(s, word_dict):
    words = set(word_dict)
    n = len(s)
    dp = [False] * (n + 1)
    dp[0] = True
    for i in range(1, n + 1):
        for j in range(i):
            if dp[j] and s[j:i] in words:
                dp[i] = True
                break
    return dp[n]

coin_change:
def coin_change(coins, amount):
    INF = float('inf')
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a and dp[a - c] + 1 < dp[a]:
                dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

lru_cache:
from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        self.cap = capacity
        self.d = OrderedDict()

    def get(self, key):
        if key not in self.d:
            return -1
        self.d.move_to_end(key)
        return self.d[key]

    def put(self, key, value):
        if key in self.d:
            self.d.move_to_end(key)
        self.d[key] = value
        if len(self.d) > self.cap:
            self.d.popitem(last=False)

edit_distance:
def edit_distance(a, b):
    m, n = len(a), len(b)
    dp = list(range(n + 1))
    for i in range(1, m + 1):
        prev = dp[0]
        dp[0] = i
        for j in range(1, n + 1):
            tmp = dp[j]
            if a[i-1] == b[j-1]:
                dp[j] = prev
            else:
                dp[j] = 1 + min(prev, dp[j], dp[j-1])
            prev = tmp
    return dp[n]

trap_rain:
def trap_rain(height):
    if not height:
        return 0
    l, r = 0, len(height) - 1
    lmax, rmax = height[l], height[r]
    total = 0
    while l < r:
        if lmax < rmax:
            l += 1
            lmax = max(lmax, height[l])
            total += lmax - height[l]
        else:
            r -= 1
            rmax = max(rmax, height[r])
            total += rmax - height[r]
    return total

median_two_sorted:
def median_two_sorted(a, b):
    merged = sorted(a + b)
    n = len(merged)
    if n == 0:
        return 0.0
    if n % 2 == 1:
        return float(merged[n // 2])
    return (merged[n // 2 - 1] + merged[n // 2]) / 2.0

regex_match:
def regex_match(s, p):
    import functools
    @functools.lru_cache(None)
    def dp(i, j):
        if j == len(p):
            return i == len(s)
        first = i < len(s) and p[j] in (s[i], '.')
        if j + 1 < len(p) and p[j+1] == '*':
            return dp(i, j+2) or (first and dp(i+1, j))
        return first and dp(i+1, j+1)
    return dp(0, 0)

n_queens:
def n_queens(n):
    count = 0
    def bt(r, cols, d1, d2):
        nonlocal count
        if r == n:
            count += 1
            return
        for c in range(n):
            if c in cols or (r-c) in d1 or (r+c) in d2:
                continue
            bt(r+1, cols|{c}, d1|{r-c}, d2|{r+c})
    bt(0, set(), set(), set())
    return count

calculate:
def calculate(s):
    s = s.replace(' ', '')
    stack = []
    num = 0
    op = '+'
    for i, ch in enumerate(s):
        if ch.isdigit():
            num = num*10 + int(ch)
        if not ch.isdigit() or i == len(s)-1:
            if op == '+': stack.append(num)
            elif op == '-': stack.append(-num)
            elif op == '*': stack.append(stack.pop()*num)
            elif op == '/': stack.append(int(stack.pop()/num))
            op = ch
            num = 0
    return sum(stack)

lis_length:
def lis_length(nums):
    import bisect
    tails = []
    for x in nums:
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

min_path_sum:
def min_path_sum(grid):
    if not grid:
        return 0
    R, C = len(grid), len(grid[0])
    dp = [[0]*C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if r == 0 and c == 0: dp[r][c] = grid[r][c]
            elif r == 0: dp[r][c] = dp[r][c-1] + grid[r][c]
            elif c == 0: dp[r][c] = dp[r-1][c] + grid[r][c]
            else: dp[r][c] = min(dp[r-1][c], dp[r][c-1]) + grid[r][c]
    return dp[-1][-1]

decode_ways:
def decode_ways(s):
    if not s or s[0] == '0':
        return 0
    a, b = 1, 1
    for i in range(1, len(s)):
        cur = 0
        if s[i] != '0': cur += b
        if 10 <= int(s[i-1:i+1]) <= 26: cur += a
        a, b = b, cur
    return b
